import React, { useCallback, useEffect, useState } from 'react';
import Switch from '@material-ui/core/Switch';
import { fetchSetupConfigApi, updateSetupConfigApi } from 'actions/admin/onboarding';
import { formResMessage } from 'utils/commonFunc';
import { SCHOOL_SETTINGS, settingChoices } from 'utils/schoolSetup';
import FilterSelect from '../Common/FilterSelect';

// The school's settings. Each switch or pick is a fixed choice (on / off, a language, one of two labels), never free text.
//  - Before the school has its first admin login the settings do not exist on the server yet (they are created with that login), so the
//    choices are kept on the page (pending / onPending) and go along when the first admin is created.
//  - Afterwards each switch or pick saves by itself, so there is nothing to submit.
const SchoolSettingsStep = ({ api, enabled, toast, pending = {}, onPending }) => {
  const [rows, setRows] = useState({}); // name -> { value, environment }
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState('');

  useEffect(() => {
    if (!enabled || !api.schoolId) return undefined;
    let cancelled = false;
    setLoading(true);
    fetchSetupConfigApi(api)
      .then(list => {
        if (cancelled) return;
        const next = {};
        (list || []).forEach(row => {
          next[row.name] = { value: row.value, environment: row.environment };
        });
        setRows(next);
      })
      .catch(err => !cancelled && toast(formResMessage(err), 'error'))
      .finally(() => !cancelled && setLoading(false));
    return () => {
      cancelled = true;
    };
  }, [enabled, api, toast]);

  const save = useCallback(
    async (name, value) => {
      if (!enabled) {
        onPending(name, value);
        return;
      }
      const before = rows[name];
      setRows(prev => ({ ...prev, [name]: { ...prev[name], value } }));
      setSaving(name);
      try {
        await updateSetupConfigApi({ ...api, name, environment: before?.environment, value });
        toast('Setting saved', 'success');
      } catch (err) {
        setRows(prev => ({ ...prev, [name]: before }));
        toast(formResMessage(err), 'error');
      } finally {
        setSaving('');
      }
    },
    [api, rows, toast, enabled, onPending]
  );

  if (loading && !Object.keys(rows).length) return <div className="text-muted">Loading the settings...</div>;

  return (
    <div>
      <div className="text-muted" style={{ fontSize: 12, marginBottom: 10 }}>
        {enabled
          ? 'Changes save as you make them.'
          : 'Choose the settings now. They are saved when the first school admin is created (step 4), and can be changed here any time after that.'}{' '}
        The school admin can also change them later from the sidebar: Admin, School settings, Common configuration.
      </div>
      {SCHOOL_SETTINGS.map(([name, def, label, picks]) => {
        const current = (enabled ? rows[name]?.value : pending[name]) ?? def;
        const pickOptions = picks ? picks.map(([value, text]) => ({ value, label: text })) : [];
        // a value saved earlier that is no longer offered (e.g. the old "Staff" teacher label) stays visible until changed
        if (picks && current && !pickOptions.some(o => o.value === current)) {
          pickOptions.push({ value: current, label: current.charAt(0) + current.slice(1).toLowerCase() });
        }
        const choice = picks ? { kind: 'pick', options: pickOptions } : settingChoices(def);
        return (
          <div className="rui-setting" key={name}>
            <div className="rui-setting-text">
              <div className="rui-setting-title">{label}</div>
            </div>
            <div className="rui-setting-control">
              {choice.kind === 'switch' ? (
                <>
                  <Switch
                    className="rui-switch"
                    size="small"
                    disabled={saving === name}
                    checked={current === choice.on}
                    onChange={e => save(name, e.target.checked ? choice.on : choice.off)}
                  />
                  <span className="rui-setting-state">{current === choice.on ? 'On' : 'Off'}</span>
                </>
              ) : (
                <FilterSelect
                  searchable={false}
                  clearable={false}
                  options={
                    choice.kind === 'pick'
                      ? choice.options
                      : choice.options.map(o => ({ value: o, label: o === 'TA' ? 'Tamil' : 'English' }))
                  }
                  value={current}
                  onChange={value => save(name, value)}
                />
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default SchoolSettingsStep;
