import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  assignSubjectTeacherApi,
  assignSubjectTeachersApi,
  fetchSubjectTeachersApi,
  removeSubjectTeacherApi,
} from 'actions/admin/onboarding';
import CustomButton from 'components/CustomButton';
import { formResMessage } from 'utils/commonFunc';
import { explainApiError, normalizeName } from 'utils/schoolSetup';
import FilterSelect from '../Common/FilterSelect';

// Which teacher takes which subject - optional, and only by choosing, so nothing can be typed wrongly. Pick a class; each of its
// subjects has a teacher pick (from School staffs). A pick saves by itself (clearing it removes the teacher), so there is nothing to
// submit. Two shortcuts ask first: one teacher for every subject of the class, and the same teachers for the class's other sections
// (classes that share the part of the name before " - ", like "I - Section A" and "I - Section B"). It stays off until the school has
// a class with a subject. Teachers can also be set later on the Assign Subjects page.
const SubjectTeachersStep = ({ api, staff, onCount, toast }) => {
  const [subjects, setSubjects] = useState(null); // null = loading
  const [courseId, setCourseId] = useState('');
  const [saving, setSaving] = useState(null); // subjectId being saved

  const load = useCallback(async () => {
    const list = (await fetchSubjectTeachersApi(api)) || [];
    setSubjects(list);
    onCount(list);
    return list;
  }, [api, onCount]);
  useEffect(() => {
    load().catch(() => setSubjects([]));
  }, [load]);

  const [onlyOpen, setOnlyOpen] = useState(false); // list only what still needs a teacher
  const [ask, setAsk] = useState(null); // { text, run } a shortcut waiting for a yes
  const [bulkTeacher, setBulkTeacher] = useState(''); // the teacher picked for the whole class, shown until the question is answered
  const closeAsk = () => {
    setAsk(null);
    setBulkTeacher('');
  };

  // every class with how many of its subjects still have no teacher
  const classes = useMemo(() => {
    const seen = new Map();
    (subjects || []).forEach(s => {
      if (!seen.has(s.courseId)) seen.set(s.courseId, { value: s.courseId, name: s.courseName, open: 0, total: 0 });
      const row = seen.get(s.courseId);
      row.total += 1;
      if (!s.employeeId) row.open += 1;
    });
    return [...seen.values()]
      .sort((a, b) => String(a.name).localeCompare(String(b.name), undefined, { numeric: true }))
      .map(c => ({ ...c, label: `${c.name} (${c.open ? `${c.open} without a teacher` : 'done'})` }));
  }, [subjects]);
  const shownClasses = onlyOpen ? classes.filter(c => c.open) : classes;
  // the first class is open to begin with (and a class that is no longer listed gives way to the next one)
  useEffect(() => {
    if (shownClasses.length && !shownClasses.some(c => String(c.value) === String(courseId))) {
      setCourseId(shownClasses[0].value);
    }
  }, [shownClasses, courseId]);

  const teachers = (staff || [])
    .filter(e => e.profession !== 'DRIVING' && e.profession !== 'NON_TEACHING')
    .map(e => ({ value: e.employeeId, label: `${e.name} (${e.email})`, name: e.name, email: e.email }));
  const classSubjects = (subjects || []).filter(
    s => String(s.courseId) === String(courseId) && (!onlyOpen || !s.employeeId)
  );
  const current = classes.find(c => String(c.value) === String(courseId));
  const openTotal = (subjects || []).filter(s => !s.employeeId).length;
  // the other sections of this standard: the same name before " - "
  const standardOf = name => String(name).split(' - ')[0].trim().toLowerCase();
  const siblings = current
    ? classes.filter(c => c.value !== current.value && standardOf(c.name) === standardOf(current.name))
    : [];

  // the teacher in the box shows the name only (the list shows the e-mail too, to tell two teachers of one name apart)
  const showTeacher = (option, { context }) =>
    context === 'menu' ? (
      <span>
        {option.name}{' '}
        <span style={{ color: '#9ca3af', fontSize: 12, display: 'block', wordBreak: 'break-all' }}>{option.email}</span>
      </span>
    ) : (
      option.name
    );

  const bulk = async (items, doneText) => {
    setSaving('bulk');
    try {
      const result = await assignSubjectTeachersApi({ ...api, items });
      toast(
        result?.errors?.length ? `${doneText} ${result.errors.length} could not be set.` : doneText,
        result?.errors?.length ? 'warning' : 'success'
      );
      await load();
    } catch (err) {
      toast(explainApiError(err, formResMessage(err)), 'error');
    } finally {
      setSaving(null);
      closeAsk();
    }
  };

  // one teacher for every subject of the class
  const askOneTeacher = employeeId => {
    const teacher = teachers.find(t => String(t.value) === String(employeeId));
    if (!teacher || !current) return;
    setBulkTeacher(employeeId);
    setAsk({
      text: `Set ${teacher.name} as the teacher of all ${current.total} subjects of ${current.name}? Teachers already set there will change.`,
      run: () =>
        bulk(
          (subjects || [])
            .filter(s => String(s.courseId) === String(courseId))
            .map(s => ({ subjectId: s.subjectId, employeeId })),
          `${teacher.name} set for all subjects of ${current.name}.`
        ),
    });
  };

  // the same teachers in the other sections of the standard, subject by subject (matched by subject name)
  const askCopy = () => {
    const mine = (subjects || []).filter(s => String(s.courseId) === String(courseId) && s.employeeId);
    const items = [];
    siblings.forEach(section => {
      (subjects || [])
        .filter(s => s.courseId === section.value)
        .forEach(s => {
          const same = mine.find(m => normalizeName(m.subjectName) === normalizeName(s.subjectName));
          if (same && same.employeeId !== s.employeeId)
            items.push({ subjectId: s.subjectId, employeeId: same.employeeId });
        });
    });
    if (!items.length) {
      toast('The other sections already have these teachers.', 'info');
      return;
    }
    setAsk({
      text: `Copy the teachers of ${current.name} to ${siblings.length} other section(s)? This sets ${items.length} subject(s), and teachers already set there will change.`,
      run: () => bulk(items, `Teachers copied to ${siblings.length} other section(s).`),
    });
  };

  const pick = async (subject, employeeId) => {
    setSaving(subject.subjectId);
    try {
      if (employeeId) {
        await assignSubjectTeacherApi({ ...api, subjectId: subject.subjectId, employeeId });
      } else {
        await removeSubjectTeacherApi({ ...api, subjectId: subject.subjectId });
      }
      toast(
        employeeId ? `Teacher set for ${subject.subjectName}.` : `Teacher removed from ${subject.subjectName}.`,
        'success'
      );
      await load();
    } catch (err) {
      toast(explainApiError(err, formResMessage(err)), 'error');
    } finally {
      setSaving(null);
    }
  };

  if (subjects === null) return <div className="text-muted">Loading...</div>;
  if (!subjects.length) {
    return (
      <div className="text-muted">
        This step is optional and is off until the school has at least one class with a subject (step 3).
      </div>
    );
  }
  const total = subjects.length;
  return (
    <div>
      <div className="d-flex flex-wrap align-items-center" style={{ gap: '4px 18px', marginBottom: 10, fontSize: 13 }}>
        <span>
          <b style={{ color: openTotal ? '#b45309' : '#15803d' }}>
            {openTotal
              ? `${openTotal} of ${total} subjects still need a teacher`
              : `All ${total} subjects have a teacher`}
          </b>
        </span>
        <label className="d-flex align-items-center mb-0" style={{ gap: 6, cursor: 'pointer', fontSize: 12 }}>
          <input type="checkbox" checked={onlyOpen} onChange={e => setOnlyOpen(e.target.checked)} />
          Show only what still needs a teacher
        </label>
        <span className="text-muted" style={{ fontSize: 12 }}>
          Each choice saves by itself.
        </span>
      </div>

      <div className="d-flex flex-wrap align-items-end" style={{ gap: 12, marginBottom: 12 }}>
        <div style={{ width: 340, maxWidth: '100%' }}>
          <label className="setup-label">Class</label>
          <FilterSelect
            options={shownClasses}
            value={courseId}
            onChange={value => {
              setCourseId(value);
              closeAsk();
            }}
            clearable={false}
            placeholder={onlyOpen ? 'Every class has its teachers' : 'Choose a class'}
          />
        </div>
        {!!current && (
          <div style={{ width: 300, maxWidth: '100%' }}>
            <label className="setup-label">One teacher for all subjects of this class</label>
            <FilterSelect
              options={teachers}
              value={bulkTeacher}
              onChange={employeeId => (employeeId ? askOneTeacher(employeeId) : closeAsk())}
              placeholder="Choose a teacher"
              formatOptionLabel={showTeacher}
            />
          </div>
        )}
        {!!siblings.length && (
          <CustomButton
            size="small"
            variant="outlined"
            name={`Copy to the other ${siblings.length} section${siblings.length > 1 ? 's' : ''}`}
            disabled={saving === 'bulk'}
            onClick={askCopy}
          />
        )}
      </div>

      {ask && (
        <div
          style={{
            padding: 10,
            borderRadius: 10,
            background: '#fff4e0',
            border: '1px solid #f5b84a',
            fontSize: 13,
            marginBottom: 12,
          }}>
          {ask.text}
          <div className="d-flex" style={{ gap: 10, marginTop: 8 }}>
            <CustomButton size="small" name="Yes, set them" disabled={saving === 'bulk'} onClick={ask.run} />
            <CustomButton size="small" variant="outlined" name="Cancel" onClick={closeAsk} />
          </div>
        </div>
      )}

      {!teachers.length && (
        <div className="text-muted" style={{ fontSize: 12, marginBottom: 8 }}>
          Add teachers in step 5 first; they appear here.
        </div>
      )}
      {classSubjects.map(subject => (
        <div className="rui-setting" key={subject.subjectId}>
          <div className="rui-setting-text">
            <div className="rui-setting-title">
              {subject.subjectName}
              {!subject.employeeId && (
                <span
                  style={{
                    marginLeft: 8,
                    padding: '1px 8px',
                    borderRadius: 999,
                    background: '#fff4e0',
                    color: '#92400e',
                    fontSize: 11,
                    fontWeight: 600,
                  }}>
                  No teacher yet
                </span>
              )}
            </div>
          </div>
          <div
            className="rui-setting-control"
            style={{ minWidth: 300, opacity: saving === subject.subjectId || saving === 'bulk' ? 0.6 : 1 }}>
            <FilterSelect
              options={teachers}
              value={subject.employeeId || ''}
              onChange={value => pick(subject, value)}
              placeholder={teachers.length ? 'Choose a teacher' : 'Add teachers in step 5 first'}
              formatOptionLabel={showTeacher}
            />
          </div>
        </div>
      ))}
      {!classSubjects.length && !!current && (
        <div className="text-muted" style={{ fontSize: 13, padding: '8px 0' }}>
          Every subject of this class has a teacher.
        </div>
      )}
    </div>
  );
};

export default SubjectTeachersStep;
