import React from 'react';
import { Col, Input } from 'reactstrap';
import { batchYearOptions } from 'utils/schoolSetup';

// The batch's start and end year as two picks instead of free text: the start year is any of the last ten years, this year or one of
// the next two, and the end year follows it (start + 1) by itself.
const YearFields = ({ startYear, onChange, disabled, md = 2 }) => {
  const years = batchYearOptions();
  return (
    <>
      <Col md={md} className="mb-2">
        <label className="setup-label">Start year</label>
        <Input
          type="select"
          value={startYear}
          disabled={disabled}
          onChange={e => onChange({ startYear: e.target.value, endYear: String(Number(e.target.value) + 1) })}>
          {years.map(year => (
            <option key={year} value={year}>
              {year}
            </option>
          ))}
        </Input>
      </Col>
      <Col md={md} className="mb-2">
        <label className="setup-label">End year</label>
        <Input type="select" value={Number(startYear) + 1} disabled>
          <option value={Number(startYear) + 1}>{Number(startYear) + 1}</option>
        </Input>
      </Col>
    </>
  );
};

export default YearFields;
