import React, { useRef, useState } from 'react';
import { Col, Input, Row } from 'reactstrap';
import YearFields from './YearFields';
import CustomButton from 'components/CustomButton';
import { addCourseToBatchApi, createBatchApi, createCourseApi, createSubjectApi } from 'actions/admin/onboarding';
import { formResMessage } from 'utils/commonFunc';
import { CLASS_LEVELS, classSubjectErrors, explainApiError, groupClasses } from 'utils/schoolSetup';
import PasteGrid from './PasteGrid';

const CLASS_COLUMNS = [
  { label: 'Class *', width: 220, aliases: ['Class name', 'Standard', 'Grade', 'Course'] },
  { label: 'Subject *', width: 200, aliases: ['Subject name', 'Subjects'] },
  {
    label: 'Level',
    width: 150,
    options: CLASS_LEVELS,
    def: 'Primary',
    hint: 'Write Primary, Secondary, Higher secondary or General. Empty means Primary.',
    aliases: ['Study level', 'Stage'],
    synonyms: { 'Higher secondary': ['Higher sec', 'HSC', 'Senior secondary'], General: ['Other'] },
  },
];
const CLASS_SAMPLE = [
  ['LKG - Section A', 'English', 'Primary'],
  ['LKG - Section A', 'Mathematics', 'Primary'],
  ['Class 11 - Section A', 'Physics', 'Higher secondary'],
];

// The school's own classes and subjects, pasted from its sheet: one row per class and subject (Class, Subject, Level), rows with the
// same Class make one class. Makes the batch, then each class (added to the batch) with its subjects. A failed class or subject stays
// red so it can be fixed and sent again; what was created is not made twice. onIssues(true) tells the page something is still red.
const PasteClassesPanel = ({ api, onCreated, onIssues, toast, setConfirm, guard, busy }) => {
  const grid = useRef(null);
  const batchRef = useRef(null); // the batch made by the first send, reused when failed rows are sent again
  const classIds = useRef(new Map()); // class key -> courseId made by an earlier send
  const [progress, setProgress] = useState('');
  const [fields, setFields] = useState({
    batchName: '',
    startYear: String(new Date().getFullYear()),
    endYear: String(new Date().getFullYear() + 1),
  });
  const setField = patch => setFields(prev => ({ ...prev, ...patch }));

  const send = async pending => {
    const year = new Date().getFullYear();
    const startYear = Number(fields.startYear) || year;
    const endYear = Number(fields.endYear) || startYear + 1;
    if (!batchRef.current) {
      batchRef.current = await createBatchApi({
        token: api.token,
        postData: {
          school: { schoolId: api.schoolId },
          name: fields.batchName.trim() || `${startYear}-${endYear}`,
          startYear,
          endYear,
        },
      });
    }
    const batch = batchRef.current;
    const groups = groupClasses(pending);
    let classesDone = 0;
    let rowsFailed = 0;
    for (const group of groups) {
      setProgress(`Creating class ${classesDone + 1} of ${groups.length}: ${group.name}`);
      let courseId = classIds.current.get(group.key);
      try {
        if (!courseId) {
          const course = await createCourseApi({
            token: api.token,
            postData: {
              school: { schoolId: api.schoolId },
              code: group.code,
              name: group.name,
              description: group.name,
              studyLevel: group.studyLevel,
              sylabusType: 'GPA',
              minimumAttendancePercent: '80',
              totalWorkingDays: '300',
              status: 'ACTIVE',
            },
          });
          courseId = course.courseId;
          classIds.current.set(group.key, courseId);
          await addCourseToBatchApi({ token: api.token, batch, courseId });
        }
      } catch (err) {
        group.subjects.forEach(s => grid.current.markFailed(s.index, explainApiError(err, formResMessage(err))));
        rowsFailed += group.subjects.length;
        // eslint-disable-next-line no-continue
        continue;
      }
      // the subjects of one class together
      const results = await Promise.allSettled(
        group.subjects.map(subject =>
          createSubjectApi({
            token: api.token,
            postData: {
              course: { courseId, school: { schoolId: api.schoolId } },
              name: subject.name,
              subjectCode: subject.code,
              description: subject.name,
              status: 'ACTIVE',
              studyLevel: group.studyLevel,
              isPracticalSubject: false,
            },
          })
        )
      );
      results.forEach((result, i) => {
        const subject = group.subjects[i];
        if (result.status === 'fulfilled') {
          grid.current.markDone(subject.index, `✓ Created #${result.value.subjectId}`);
        } else {
          rowsFailed += 1;
          grid.current.markFailed(subject.index, explainApiError(result.reason, formResMessage(result.reason)));
        }
      });
      classesDone += 1;
    }
    setProgress('');
    onIssues(rowsFailed > 0);
    return { classes: classesDone, failed: rowsFailed };
  };

  const create = () => {
    const pending = grid.current.pending();
    if (!pending.length) {
      toast('Nothing to send. Type or paste class and subject rows first.', 'warning');
      return;
    }
    if (grid.current.problems()) {
      toast('Fix the red rows first (see the Status column).', 'warning');
      return;
    }
    const classCount = groupClasses(pending).length;
    setConfirm({
      message: `Create ${batchRef.current ? 'these' : 'the batch with'} ${classCount} class(es) and ${
        pending.length
      } subject(s)?`,
      onYes: () =>
        guard('init', async () => {
          try {
            const result = await send(pending);
            toast(
              `Created ${result.classes} class(es)${result.failed ? `, ${result.failed} row(s) failed` : ''}`,
              result.failed ? 'warning' : 'success'
            );
          } finally {
            setProgress('');
            await onCreated();
          }
        }),
    });
  };

  return (
    <div>
      <Row form>
        <Col md={4} className="mb-2">
          <label className="setup-label">Batch name</label>
          <Input
            value={fields.batchName}
            placeholder="Automatic"
            disabled={!!batchRef.current}
            onChange={e => setField({ batchName: e.target.value })}
          />
        </Col>
        <YearFields startYear={fields.startYear} disabled={!!batchRef.current} onChange={setField} />
      </Row>
      <PasteGrid
        ref={grid}
        columns={CLASS_COLUMNS}
        validate={classSubjectErrors}
        minRows={1}
        what="subject (one row per class and subject)"
        templateName="school-classes-template.xlsx"
        templateSample={CLASS_SAMPLE}
      />
      <div className="d-flex align-items-center mt-2" style={{ gap: 10 }}>
        <CustomButton
          size="small"
          disabled={busy === 'init'}
          onClick={create}
          name="Create batch, classes & subjects"
        />
        <span className="text-muted" style={{ fontSize: 12 }}>
          {progress ||
            'Created rows turn green and are locked. Failed rows stay red so you can fix them and send again.'}
        </span>
      </div>
    </div>
  );
};

export default PasteClassesPanel;
