// A collapsible section. A finished step (done) folds itself away and says "Done"; it is read-only when opened again unless locked is
// false (a step that can still be changed). Steps without a done flag stay open and keep what was typed while folded (they are
// hidden, not removed). count is a small note after the title (e.g. how many logins exist).
const Step = ({ number, title, done, locked, count, hint, doneNote, children }) => {
  const [open, setOpen] = useState(done !== true);
  useEffect(() => {
    if (done) setOpen(false);
  }, [done]);
  return (
    <Card style={{ marginBottom: 20 }}>
      <CardBody>
        <div
          role="button"
          tabIndex={0}
          className="d-flex align-items-center"
          style={{ gap: 10, cursor: 'pointer' }}
          onClick={() => setOpen(o => !o)}
          onKeyDown={e => e.key === 'Enter' && setOpen(o => !o)}>
          <span
            style={{
              width: 26,
              height: 26,
              borderRadius: '50%',
              background: done ? '#15803d' : colors.accent,
              color: '#fff',
              display: 'inline-flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontSize: 13,
              fontWeight: 700,
            }}>
            {done ? '✓' : number}
          </span>
          <h5 className="setup-step-title">{title}</h5>
          {count !== undefined && <span style={{ fontSize: 12, color: '#6b778a', fontWeight: 600 }}>{count}</span>}
          {done !== undefined && (
            <span
              style={{
                fontSize: 12,
                fontWeight: 700,
                padding: '2px 10px',
                borderRadius: 999,
                background: done ? '#e2ffde' : '#fff4e0',
                color: done ? '#1f7a2e' : '#92400e',
              }}>
              {done ? 'Done' : 'To do'}
            </span>
          )}
          <span style={{ marginLeft: 'auto', color: '#6b7280', display: 'inline-flex' }}>
            {open ? <ExpandMoreIcon /> : <ChevronRightIcon />}
          </span>
        </div>
        <div style={{ display: open ? 'block' : 'none', marginTop: 8 }}>
          {done && doneNote && (
            <div className="text-muted" style={{ fontSize: 12, marginBottom: 10 }}>
              {doneNote}
            </div>
          )}
          {!done && hint && (
            <div className="text-muted" style={{ fontSize: 12, marginBottom: 10 }}>
              {hint}
            </div>
          )}
          <fieldset
            disabled={locked === undefined ? !!done : locked}
            style={{
              border: 0,
              padding: 0,
              margin: 0,
              minWidth: 0,
              opacity: (locked === undefined ? done : locked) ? 0.6 : 1,
            }}>
            {children}
          </fieldset>
        </div>
      </CardBody>
    </Card>
  );
};

// The logins a school already has (so nothing is added twice), most useful columns only, scrolling when long.
const ExistingList = ({ rows, loading, columns, empty }) => {
  if (loading && !rows.length) return <div className="text-muted mb-2">Loading...</div>;
  if (!rows.length) return <div className="text-muted mb-2">{empty}</div>;
  return (
    <ChainScroll
      style={{ maxHeight: 240, overflowY: 'auto', marginBottom: 14, border: '1px solid #eceff3', borderRadius: 10 }}>
      <table className="table table-sm mb-0" style={{ fontSize: 13 }}>
        <thead>
          <tr>
            {columns.map(c => (
              <th key={c.label}>{c.label}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map(row => (
            <tr key={row.key}>
              {columns.map(c => (
                <td key={c.label}>{c.get(row)}</td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </ChainScroll>
  );
};

// One short label on one line (hints go in the field's placeholder) so every input in a row lines up.
const Field = ({ label, children, md = 3 }) => (
  <Col md={md} className="mb-2">
    <label className="setup-label">{label}</label>
    {children}
  </Col>
);

// First-time setup of a school, in the order it has to be done: the batch with its classes and subjects, the admin (and dean)
// logins with the school's settings, any more admins, then all the teachers pasted straight from the school's Excel sheet. Each
// step can be done once for a new school; everything can be changed later on the usual pages.
const SchoolSetupPage = () => {
  const dispatch = useDispatch();
  const token = useSelector(state => state.auth.loggedUserToken);
  const role = useSelector(state => state.auth.loggedUserRole);
  // The school being set up comes from the address (/admin/schools/:schoolId/setup, opened from the Schools page by the super admin);
  // its name travels with the click. Without them it falls back to the school selected at the top.
  const history = useHistory();
  const location = useLocation();
  const params = useParams();
  const picked = getGlobalSchoolUtils();
  const schoolId = Number(params.schoolId) || picked?.schoolId;
  const school = {
    schoolId,
    schoolName: location.state?.schoolName || (schoolId === picked?.schoolId ? picked?.schoolName : ''),
  };
  const api = useMemo(() => ({ token, schoolId }), [token, schoolId]);
  const toast = useCallback((message, type) => dispatch(showToast(message, type)), [dispatch]);

  const [status, setStatus] = useState(null);
  const [creds, setCreds] = useState([]);
  const [confirm, setConfirm] = useState(null);
  const [busy, setBusy] = useState('');
  const [setupResult, setSetupResult] = useState(null);
  const [schoolInfo, setSchoolInfo] = useState(null);
  const [admins, setAdmins] = useState(null); // null = loading
  const [staff, setStaff] = useState(null);
  const [classMode, setClassMode] = useState('template'); // 'template' | 'paste'
  const [pasteIssues, setPasteIssues] = useState(false);
  const [pendingSettings, setPendingSettings] = useState({}); // settings chosen before the school has its first admin
  // the settings step is done once every setting has a value (each starts with its default)
  const settingsComplete = SCHOOL_SETTINGS.every(([name, def]) => String(pendingSettings[name] ?? def).trim() !== '');
  const [subjectCount, setSubjectCount] = useState(null);

  const [init, setInit] = useState({
    batchName: '',
    startYear: String(new Date().getFullYear()),
    endYear: String(new Date().getFullYear() + 1),
    includeKg: 'true',
    fromGrade: 1,
    toGrade: 12,
    sections: 'A,B,C',
  });
  const adminGrid = useRef(null);
  const employeeGrid = useRef(null);

  const refreshStatus = useCallback(
    () =>
      schoolId && role === constants.roles.SA
        ? fetchSetupStatusApi(api)
            .then(setStatus)
            .catch(() => setStatus(null))
        : Promise.resolve(),
    [api, schoolId, role]
  );
  useEffect(() => {
    refreshStatus();
  }, [refreshStatus]);

  // The school's own details, and the logins it has now (read again after every create below).
  useEffect(() => {
    let cancelled = false;
    fetchAllSchoolsPlainApi({ token })
      .then(list => !cancelled && setSchoolInfo(list.find(item => item.schoolId === schoolId) || null))
      .catch(() => {});
    return () => {
      cancelled = true;
    };
  }, [token, schoolId]);
  const refreshPeople = useCallback(async () => {
    if (!schoolId || role !== constants.roles.SA) return;
    fetchSchoolAdminsPlainApi(api)
      .then(setAdmins)
      .catch(() => setAdmins([]));
    fetchSchoolEmployeesApi(api).then(list => setStaff(list || []));
  }, [api, schoolId, role]);
  useEffect(() => {
    refreshPeople();
  }, [refreshPeople]);

  const onSubjectCount = useCallback(
    list => setSubjectCount({ total: list.length, open: list.filter(item => !item.employeeId).length }),
    []
  );
  const addCreds = users => setCreds(prev => [...prev, ...(users || []).map(toCredential)]);
  const setInitField = patch => setInit(prev => ({ ...prev, ...patch }));
  const estimate = estimateClasses({ ...init, includeKg: init.includeKg === 'true' });
  const value = v => (String(v).trim() === '' ? undefined : String(v).trim());

  const guard = async (name, work) => {
    setBusy(name);
    try {
      await work();
    } catch (err) {
      toast(explainApiError(err, formResMessage(err)), 'error');
    } finally {
      setBusy('');
      setConfirm(null);
    }
  };

  const createClasses = () =>
    setConfirm({
      message: 'Create the batch, classes and subjects? This can be done only once for a school.',
      onYes: () =>
        guard('init', async () => {
          const result = await initializeSchoolApi({
            ...api,
            postData: {
              batchName: value(init.batchName),
              startYear: value(init.startYear) && Number(init.startYear),
              endYear: value(init.endYear) && Number(init.endYear),
              includeKg: init.includeKg === 'true',
              fromGrade: Number(init.fromGrade) || undefined,
              toGrade: Number(init.toGrade) || undefined,
              sections: String(init.sections)
                .split(',')
                .map(s => s.trim())
                .filter(Boolean),
            },
          });
          toast(`Created ${result.courses} classes and ${result.subjects} subjects`, 'success');
          await refreshStatus();
        }),
    });

  // Admin and dean logins in one grid. The first Admin row of a new school also sets the school up (its default settings and module
  // permissions are made with that first admin); every other row, and every row once the school is set up, is added as a login.
  const createAdmins = () => {
    const pending = adminGrid.current.pending();
    if (!pending.length) {
      toast('Nothing to send. Fill at least one row.', 'warning');
      return;
    }
    if (adminGrid.current.problems()) {
      toast('Fix the red rows first (see the Status column).', 'warning');
      return;
    }
    const needsSetup = !status?.setupDone;
    const first = needsSetup ? pending.find(({ values }) => (values[2] || 'ADMIN') === 'ADMIN') : null;
    if (needsSetup && !first) {
      toast('A new school needs at least one Admin row: the first admin sets the school up.', 'warning');
      return;
    }
    setConfirm({
      message: `Create ${pending.length} login(s)?`,
      onYes: () =>
        guard('admins', async () => {
          const created = [];
          const send = [first, ...pending.filter(row => row !== first)].filter(Boolean);
          for (const { index, values } of send) {
            try {
              let user;
              if (first?.index === index) {
                const result = await setupSchoolApi({
                  ...api,
                  postData: {
                    adminName: value(values[0]),
                    adminEmail: value(values[1]),
                    environment: 'PROD',
                    configOverrides: changedSettings(SCHOOL_SETTINGS, pendingSettings),
                  },
                });
                setSetupResult(result);
                [user] = result.users || [];
                created.push(...(result.users || []));
              } else {
                user = await addAdminApi({ ...api, postData: adminBody(values) });
                created.push(user);
              }
              adminGrid.current.markDone(index, `✓ Created #${user.userId}`);
            } catch (err) {
              adminGrid.current.markFailed(index, explainApiError(err, formResMessage(err)));
              // the school was not set up, so the rows after the first cannot be added yet
              if (first?.index === index) break;
            }
          }
          addCreds(created);
          await refreshStatus();
          refreshPeople();
        }),
    });
  };

  const createEmployees = () => {
    const pending = employeeGrid.current.pending();
    if (!pending.length) {
      toast('Nothing to send. Type or paste staff rows first.', 'warning');
      return;
    }
    if (employeeGrid.current.problems()) {
      toast('Fix the red rows first (see the Status column).', 'warning');
      return;
    }
    setConfirm({
      message: `Create ${pending.length} staff login(s)?`,
      onYes: () =>
        guard('employees', async () => {
          const byEmail = {};
          pending.forEach(({ index, values }) => {
            byEmail[String(values[1]).toLowerCase()] = index;
          });
          const isDriver = ({ values }) => values[2] === 'Driver';
          const drivers = pending.filter(isDriver);
          const others = pending.filter(row => !isDriver(row));
          const created = [];
          const failures = [];
          if (others.length) {
            try {
              const bulk = await addTeachersApi({ ...api, postData: others.map(({ values }) => teacherBody(values)) });
              (bulk.created || []).forEach(user => {
                const index = byEmail[String(user.loginId).toLowerCase()];
                if (index !== undefined) employeeGrid.current.markDone(index, `✓ Created #${user.userId}`);
              });
              Object.entries(errorsByEmail(bulk.errors)).forEach(([email, reason]) => {
                if (byEmail[email] !== undefined) employeeGrid.current.markFailed(byEmail[email], reason);
              });
              created.push(...(bulk.created || []));
              failures.push(...(bulk.errors || []));
            } catch (err) {
              // the whole call failed: keep these rows red with the reason, and still send the drivers below
              others.forEach(({ index, values }) => {
                employeeGrid.current.markFailed(index, explainApiError(err, formResMessage(err)));
                failures.push(String(values[1]));
              });
            }
          }
          // a driver goes through the driver endpoint (employee with profession DRIVING and a driver login), one at a time
          for (const { index, values } of drivers) {
            try {
              const driver = (await saveDriverApi({ postData: driverBody(values, schoolId), token })).data;
              employeeGrid.current.markDone(index, `✓ Created #${driver.employeeId}`);
              created.push({
                userId: driver.employeeId,
                name: driver.name,
                loginId: driver.email,
                role: 'ROLE_DRIVER',
              });
            } catch (err) {
              employeeGrid.current.markFailed(index, explainApiError(err, formResMessage(err)));
              failures.push(String(values[1]));
            }
          }
          const result = { created, errors: failures };
          addCreds(result.created);
          toast(
            `Created ${(result.created || []).length}, failed ${(result.errors || []).length}`,
            (result.errors || []).length ? 'warning' : 'success'
          );
          await refreshStatus();
          refreshPeople();
        }),
    });
  };

  const copyCreds = () => {
    const text = credentialsTsv(creds);
    if (navigator.clipboard && window.isSecureContext) {
      navigator.clipboard.writeText(text).then(() => toast('Copied. Paste it into Excel.', 'success'));
    } else {
      const area = document.createElement('textarea');
      area.value = text;
      document.body.appendChild(area);
      area.select();
      document.execCommand('copy');
      area.remove();
      toast('Copied. Paste it into Excel.', 'success');
    }
  };
  const downloadCreds = () => {
    const link = document.createElement('a');
    link.href = URL.createObjectURL(new Blob([credentialsCsv(creds)], { type: 'text/csv' }));
    link.download = `school-${schoolId}-logins.csv`;
    link.click();
  };

  // Setting a school up is for the super admin only. The address is not role-checked by the app, so the page refuses itself (the server
  // refuses too).
  if (role !== constants.roles.SA) {
    return (
      <div className="content">
        <EmptyState
          icon="fas fa-lock"
          title="School setup is for the super admin"
          subtitle="Ask the super admin to set this school up."
        />
      </div>
    );
  }
  if (!schoolId) return <EmptyState title="Please select a school first" />;

  return (
    <div className="content setup-page">
      <Card style={{ marginBottom: 20 }}>
        <CardBody>
          <div className="d-flex align-items-center justify-content-between" style={{ gap: 10 }}>
            <h4 className="setup-title" style={{ marginBottom: 0 }}>
              School setup
            </h4>
            <CustomButton
              size="small"
              variant="outlined"
              name="Back to Schools"
              onClick={() => history.push('/admin/schools')}
            />
          </div>
          <div className="text-muted" style={{ fontSize: 13 }}>
            {school?.schoolName || schoolInfo?.schoolName || `School #${schoolId}`} (id {schoolId}). Do the steps in
            order; a finished step is folded (open it to see or change it). Everything can be changed later on the usual
            pages.
            {status && !(status.initialized && status.setupDone) && (
              <>
                {' '}
                <b>
                  Next:{' '}
                  {!status.initialized
                    ? 'step 3, the batch, classes and subjects.'
                    : 'step 4, the first admin (it saves the settings from step 2).'}
                </b>
              </>
            )}
          </div>
        </CardBody>
      </Card>

      <Step
        number={1}
        title="School creation"
        done={!!school.schoolId}
        locked={false}
        doneNote="The school exists. Change its details on the Schools page.">
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '4px 28px', fontSize: 13, marginBottom: 10 }}>
          {[
            ['Code', schoolInfo?.schoolCode],
            ['Name', schoolInfo?.schoolName || school.schoolName],
            ['Address', schoolInfo?.address],
            ['Phone', schoolInfo?.phoneNumber],
            ['Country', schoolInfo?.country],
            ['Currency', schoolInfo?.currencyType],
          ]
            .filter(([, v]) => !!v)
            .map(([label, v]) => (
              <span key={label}>
                <span className="text-muted">{label}: </span>
                <b>{v}</b>
              </span>
            ))}
        </div>
        <CustomButton
          size="small"
          variant="outlined"
          name="Edit on Schools page"
          onClick={() => history.push('/admin/schools')}
        />
      </Step>

      <Step number={2} title="School settings" done={settingsComplete} locked={false}>
        <SchoolSettingsStep
          api={api}
          enabled={!!status?.setupDone}
          toast={toast}
          pending={pendingSettings}
          onPending={(name, value) => setPendingSettings(prev => ({ ...prev, [name]: value }))}
        />
      </Step>

      <Step
        number={3}
        title="Batch, classes & subjects"
        done={status ? status.initialized && !pasteIssues : undefined}
        locked={false}
        doneNote="This step can be done only once. What was created is listed below; change batches, classes and subjects later on their own pages."
        hint="Use the standard template (classes with sections and their default subjects in one go), or paste the school's own classes and subjects from its sheet. Names can be edited later.">
        {status?.initialized && !pasteIssues && (
          <CreatedClassesList api={api} refreshKey={`${status.courses}-${status.subjects}`} />
        )}
        {(!status?.initialized || pasteIssues) && (
          <div className="rui-segments" role="radiogroup" style={{ marginBottom: 12 }}>
            {[
              ['template', 'Standard template'],
              ['paste', "School's own classes & subjects (paste)"],
            ].map(([key, label]) => (
              <button
                key={key}
                type="button"
                role="radio"
                aria-checked={classMode === key}
                className={classMode === key ? 'on' : ''}
                disabled={pasteIssues && key === 'template'}
                onClick={() => setClassMode(key)}>
                {label}
              </button>
            ))}
          </div>
        )}
        {(!status?.initialized || pasteIssues) && classMode === 'paste' && (
          <PasteClassesPanel
            api={api}
            toast={toast}
            setConfirm={setConfirm}
            guard={guard}
            busy={busy}
            onIssues={setPasteIssues}
            onCreated={async () => {
              await refreshStatus();
            }}
          />
        )}
        {!status?.initialized && classMode !== 'paste' && (
          <>
            <Row form>
              <Field label="Batch name" md={4}>
                <Input
                  value={init.batchName}
                  placeholder="Automatic"
                  onChange={e => setInitField({ batchName: e.target.value })}
                />
              </Field>
              <YearFields startYear={init.startYear} onChange={setInitField} />
              <Field label="Include KG classes" md={4}>
                <Input type="select" value={init.includeKg} onChange={e => setInitField({ includeKg: e.target.value })}>
                  <option value="true">Yes</option>
                  <option value="false">No</option>
                </Input>
              </Field>
            </Row>
            <Row form>
              <Field label="From grade" md={2}>
                <Input
                  type="number"
                  min="1"
                  max="12"
                  value={init.fromGrade}
                  onChange={e => setInitField({ fromGrade: e.target.value })}
                />
              </Field>
              <Field label="To grade" md={2}>
                <Input
                  type="number"
                  min="1"
                  max="12"
                  value={init.toGrade}
                  onChange={e => setInitField({ toGrade: e.target.value })}
                />
              </Field>
              <Field label="Sections" md={4}>
                <Input
                  value={init.sections}
                  placeholder="Comma separated, e.g. A,B,C"
                  onChange={e => setInitField({ sections: e.target.value })}
                />
              </Field>
            </Row>
            <div className="text-muted" style={{ fontSize: 12, marginBottom: 10 }}>
              Will create about {estimate.classes} classes ({estimate.standards} standards × {estimate.sections}{' '}
              sections) with their subjects.
            </div>
            <CustomButton
              size="small"
              disabled={busy === 'init'}
              onClick={createClasses}
              name="Create batch, classes & subjects"
            />
          </>
        )}
      </Step>

      <Step
        number={4}
        title="School admins"
        count={admins ? `${admins.length} existing` : undefined}
        hint={
          status?.setupDone
            ? 'Add more admins or deans any time. Every new login starts with the default password; ask them to change it after the first sign-in.'
            : "A new school needs at least one Admin row first: the school's main login (it sees only this school and has no setup). It also creates the school's default settings and module permissions (step 2). Dean rows are added after it. Every new login starts with the default password."
        }>
        <ExistingList
          rows={(admins || []).map(a => ({ ...a, key: a.userId || a.email }))}
          loading={admins === null}
          empty="No admin or dean yet."
          columns={[
            { label: 'Name', get: r => r.name },
            { label: 'Login', get: r => r.email },
            { label: 'Role', get: r => r.designation },
          ]}
        />
        <PasteGrid
          ref={adminGrid}
          columns={ADMIN_COLUMNS}
          validate={personErrors}
          minRows={1}
          what="admin or dean"
          templateName="school-admins-template.xlsx"
          templateSample={ADMIN_SAMPLE}
        />
        <CustomButton
          size="small"
          className="mt-2"
          disabled={busy === 'admins'}
          onClick={createAdmins}
          name="Create logins"
        />
        {setupResult && (
          <div style={{ marginTop: 12 }}>
            School setup done: {setupResult.commonConfigs} settings, {setupResult.modulePermissions} module permissions.
          </div>
        )}
      </Step>

      <Step
        number={5}
        title="School staffs (teachers, workers, drivers)"
        count={staff ? `${staff.length} existing` : undefined}
        hint="Add the school's teachers, workers (non-teaching staff) and drivers. Each one gets a login with the default password.">
        <ExistingList
          rows={(staff || []).map(e => ({ ...e, key: e.employeeId }))}
          loading={staff === null}
          empty="No staff yet."
          columns={[
            { label: 'Name', get: r => r.name },
            { label: 'Login', get: r => r.email },
            {
              label: 'Type',
              get: r => ({ NON_TEACHING: 'Non-teaching', DRIVING: 'Driver' }[r.profession] || 'Teaching'),
            },
            { label: 'Code', get: r => r.code },
          ]}
        />
        <PasteGrid
          ref={employeeGrid}
          columns={EMPLOYEE_COLUMNS}
          validate={personErrors}
          minRows={1}
          what="staff member"
          templateName="school-staff-template.xlsx"
          templateSample={EMPLOYEE_SAMPLE}
        />
        <div className="d-flex align-items-center mt-2" style={{ gap: 10 }}>
          <CustomButton
            size="small"
            disabled={busy === 'employees'}
            onClick={createEmployees}
            name="Create staff logins"
          />
          <span className="text-muted" style={{ fontSize: 12 }}>
            Created rows turn green and are locked. Failed rows stay red so you can fix them and send again.
          </span>
        </div>
      </Step>

      <Step
        number={6}
        title="Subject teachers (optional)"
        count={
          subjectCount?.total ? `${subjectCount.total} subjects, ${subjectCount.open} without a teacher` : undefined
        }>
        <SubjectTeachersStep api={api} staff={staff || []} onCount={onSubjectCount} toast={toast} />
      </Step>

      {creds.length > 0 && (
        <Card style={{ marginBottom: 20 }}>
          <CardBody>
            <h5 className="setup-step-title" style={{ marginBottom: 8 }}>
              Generated logins
            </h5>
            <div
              style={{
                background: '#fff4e0',
                border: '1px solid #f5b84a',
                padding: 10,
                borderRadius: 12,
                marginBottom: 10,
                fontSize: 13,
              }}>
              Every login below starts with the default password. Copy or download this list to hand the logins out, and
              ask everyone to change their password after the first sign-in.
            </div>
            <div className="d-flex" style={{ gap: 8, marginBottom: 8 }}>
              <CustomButton size="small" variant="outlined" name="Copy (paste into Excel)" onClick={copyCreds} />
              <CustomButton size="small" variant="outlined" name="Download CSV" onClick={downloadCreds} />
            </div>
            <table className="table">
              <thead>
                <tr>
                  <th>Name</th>
                  <th>Login</th>
                  <th>Role</th>
                  <th>Password</th>
                </tr>
              </thead>
              <tbody>
                {creds.map(c => (
                  <tr key={`${c.login}-${c.role}`}>
                    <td>{c.name}</td>
                    <td>{c.login}</td>
                    <td>{c.role}</td>
                    <td style={c.password === DEFAULT_PASSWORD_LABEL ? undefined : { fontFamily: 'monospace' }}>
                      {c.password}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </CardBody>
        </Card>
      )}

      <ConfirmModal
        size="md"
        loading={!!busy}
        confirmModalOpen={!!confirm}
        confirmMessage={confirm?.message}
        deleteConfirm={() => confirm?.onYes()}
        deleteCancel={() => setConfirm(null)}
      />
    </div>
  );
};

export default SchoolSetupPage;
