import React, { useRef } from 'react';
import { useChainWheel } from 'utils/useContainWheel';

// A scrolling box (give it a max-height and overflow in its class or style) that follows the hover: the wheel over the box scrolls the
// box only, and once the box is at its top or end the same wheel carries on with the page; the wheel anywhere else scrolls the page.
// Without this the page's own wheel script also scrolled the page while the box scrolled, so both moved at once.
const ChainScroll = ({ children, ...rest }) => {
  const ref = useRef(null);
  useChainWheel(ref);
  return (
    <div ref={ref} {...rest}>
      {children}
    </div>
  );
};

export default ChainScroll;
