import React, { forwardRef, useImperativeHandle, useMemo, useRef, useState } from 'react';
import { Modal, ModalBody, ModalFooter, ModalHeader } from 'reactstrap';
import CustomButton from 'components/CustomButton';
import colors from 'config/colors';
import {
  downloadTemplate,
  isBlankRow,
  isGridPaste,
  normalizeCell,
  placeTable,
  readSheetFile,
  splitTable,
} from 'utils/schoolSetup';

// A small spreadsheet. Three ways in: type, paste from Excel (a column, several columns, or the whole sheet with its header row -
// columns are matched by their header names, see placeTable), or upload an .xlsx / .csv file (also by dropping it on the grid). Red
// cells need fixing; rows that were created turn green and are locked. The page reads it through the ref:
//   pending()            -> [{ index, values }] rows with something in them that are not created yet
//   problems()           -> how many pending rows still have a mistake
//   markDone(i, text) / markFailed(i, message)
// columns: [{ label, width, options?, def?, aliases?, synonyms? }] (options = a drop-down, def = the value of an empty cell, aliases =
// other header names of the column, synonyms = { option: [other words for it] })
// column.hint: one line shown under the sample sheet about the values the column takes.
// what: what one row is ("staff member", "admin", "subject"), for the instructions. templateName / templateSample: the file "Download
// template" saves (headers plus sample rows), also shown as a small picture of the sheet.
const baseName = column =>
  column.label
    .replace(/\(.*?\)/g, '')
    .replace('*', '')
    .trim();
const blankRow = columns => ({ values: columns.map(c => c.def || ''), locked: false, done: '', server: '' });
const withRows = (rows, columns, count) => {
  const next = [...rows];
  while (next.length < count) next.push(blankRow(columns));
  return next;
};
// every cell looks like a box you can click into
const cell = {
  width: '100%',
  padding: '6px 8px',
  border: '1px solid #e1daee',
  borderRadius: 8,
  background: '#fff',
  outline: 'none',
  fontSize: 13,
};

const PasteGrid = forwardRef(({ columns, validate, minRows = 5, templateName, templateSample, what = 'row' }, ref) => {
  const [rows, setRows] = useState(() => withRows([], columns, minRows));
  const [selected, setSelected] = useState({});
  const [note, setNote] = useState(null); // { text, tone } what the last paste / upload did
  const optionColumn = columns.findIndex(c => c.options); // the drop-down column that can be set for every row at once (-1 = none)
  const [fillValue, setFillValue] = useState('');
  const [pasteOpen, setPasteOpen] = useState(false); // the "Paste from Excel" window
  const [pasteText, setPasteText] = useState('');
  const [dragging, setDragging] = useState(false);
  const box = useRef(null);
  const fileInput = useRef(null);
  const history = useRef([]); // rows before each bulk change, for Undo
  const defaults = columns.map(c => c.def || '');

  const status = (row, index) => {
    if (row.locked) return { text: row.done || 'Done', tone: '#15803d', bad: [] };
    if (isBlankRow(row.values, defaults)) return { text: '', tone: '', bad: [] };
    if (row.server) return { text: row.server, tone: '#b91c1c', bad: [] };
    const errors = validate
      ? validate(
          row.values,
          index,
          rows.map(r => r.values)
        )
      : [];
    if (errors.length) return { text: errors[0][1], tone: '#b91c1c', bad: errors.map(e => e[0]) };
    return { text: 'Ready', tone: '#6b7280', bad: [] };
  };
  const statuses = rows.map(status);

  useImperativeHandle(ref, () => ({
    pending: () =>
      rows
        .map((row, index) => ({ index, values: row.values, row }))
        .filter(x => !x.row.locked && !isBlankRow(x.values, defaults)),
    problems: () => statuses.filter(s => s.tone === '#b91c1c').length,
    markDone: (index, text) =>
      setRows(prev => prev.map((r, i) => (i === index ? { ...r, locked: true, done: text, server: '' } : r))),
    markFailed: (index, message) => setRows(prev => prev.map((r, i) => (i === index ? { ...r, server: message } : r))),
  }));

  const remember = () => {
    history.current = [...history.current.slice(-19), rows];
  };

  const focusCell = (r, c) => {
    const el = box.current?.querySelector(`[data-r="${r}"][data-c="${c}"]`);
    if (el) {
      el.focus();
      if (el.select) el.select();
    }
  };

  const edit = (r, c, value) =>
    setRows(prev =>
      prev.map((row, i) =>
        i === r && !row.locked ? { ...row, values: row.values.map((v, j) => (j === c ? value : v)), server: '' } : row
      )
    );

  // Puts a table (from a paste or a file) into the grid from row startRow: matched by header names when the first row has them,
  // otherwise in order from column startCol. Rows that are already created (locked) are skipped.
  const applyTable = (table, startRow, startCol, source) => {
    const placed = placeTable(table, columns, startCol);
    if (!placed.rows.length) {
      setNote({
        text: `No rows found${source ? ` in ${source}` : ''}. The first row should be the headers.`,
        tone: '#b45309',
      });
      return;
    }
    remember();
    let unknown = 0;
    const next = withRows(rows, columns, startRow + placed.rows.length + 1).map(row => ({
      ...row,
      values: [...row.values],
    }));
    placed.rows.forEach((cells, offset) => {
      const row = next[startRow + offset];
      if (row.locked) return;
      cells.forEach((value, j) => {
        if (value === undefined) return;
        const cell = normalizeCell(columns[j], value);
        if (cell === null) unknown += 1;
        row.values[j] = cell === null ? columns[j].def || '' : cell;
      });
      row.server = '';
    });
    setRows(next);
    const names = placed.matched.join(', ');
    setNote({
      text: `${source ? `Loaded ${placed.rows.length} row(s) from ${source}` : `Pasted ${placed.rows.length} row(s)`}${
        placed.mode === 'header' ? `. Matched: ${names}` : ''
      }${placed.skippedAbove ? `. Skipped ${placed.skippedAbove} line(s) above the column names` : ''}${
        placed.ignored.length ? `. Ignored columns: ${placed.ignored.join(', ')}` : ''
      }${placed.dropped ? '. The serial-number column was skipped' : ''}${
        unknown ? `. ${unknown} value(s) in a drop-down were not recognised and were reset to the default` : ''
      }.`,
      tone: unknown ? '#b45309' : '#15803d',
    });
  };

  const paste = (event, r, c) => {
    const text = event.clipboardData.getData('text');
    if (!isGridPaste(text)) return; // one value: an ordinary paste
    event.preventDefault();
    applyTable(splitTable(text), r, c, '');
  };

  // the first row after the last one that is created or has something in it: a file or the paste box fills from there
  const firstFreeRow = () => {
    let start = 0;
    rows.forEach((row, i) => {
      if (row.locked || !isBlankRow(row.values, defaults)) start = i + 1;
    });
    return start;
  };

  // The "Paste from Excel" window: what was pasted is read and shown first; nothing is put in the table until "Add to table".
  const pasted = useMemo(() => {
    const table = splitTable(pasteText);
    if (!table.length) return null;
    const placed = placeTable(table, columns, 0);
    const preview = placed.rows.slice(0, 6).map(cells =>
      columns.map((col, j) => {
        if (cells[j] === undefined) return '';
        const value = normalizeCell(col, cells[j]);
        return value === null ? { bad: cells[j] } : value;
      })
    );
    return { table, placed, preview };
  }, [pasteText]);
  const closePaste = () => {
    setPasteOpen(false);
    setPasteText('');
  };
  const addPasted = () => {
    if (!pasted?.placed.rows.length) return;
    applyTable(pasted.table, firstFreeRow(), 0, '');
    closePaste();
  };

  // an uploaded file goes in below the rows already there
  const loadFile = async file => {
    if (!file) return;
    if (!/\.(xlsx|xlsm|xls|csv|tsv|txt)$/i.test(file.name)) {
      setNote({ text: 'Please choose an Excel (.xlsx, .xls) or CSV file.', tone: '#b91c1c' });
      return;
    }
    try {
      applyTable(await readSheetFile(file), firstFreeRow(), 0, file.name);
    } catch (err) {
      setNote({ text: `Could not read ${file.name}. Is it a valid Excel or CSV file?`, tone: '#b91c1c' });
    }
  };

  const undo = () => {
    const last = history.current.pop();
    if (last) {
      setRows(last);
      setSelected({});
      setNote({ text: 'Undone.', tone: '#6b7280' });
    }
  };

  // sets the drop-down column (Type / Role / Level) of every row that has something in it
  const applyToAll = () => {
    const column = columns[optionColumn];
    const value = normalizeCell(column, fillValue);
    if (!fillValue || value === null) return;
    remember();
    setRows(prev =>
      prev.map(row =>
        row.locked || isBlankRow(row.values, defaults)
          ? row
          : { ...row, values: row.values.map((v, j) => (j === optionColumn ? value : v)), server: '' }
      )
    );
    setNote({ text: `${baseName(column)} set to ${value} for every row.`, tone: '#15803d' });
  };

  const keyDown = (event, r, c) => {
    if ((event.ctrlKey || event.metaKey) && (event.key === 'd' || event.key === 'D')) {
      // copy the box above, like Excel
      event.preventDefault();
      if (r > 0 && !rows[r].locked) edit(r, c, rows[r - 1].values[c]);
    } else if (event.key === 'Enter' || (event.key === 'ArrowDown' && event.target.tagName !== 'SELECT')) {
      event.preventDefault();
      if (r + 1 >= rows.length) setRows(prev => withRows(prev, columns, r + 2));
      setTimeout(() => focusCell(r + 1, c), 0);
    } else if (event.key === 'ArrowUp' && event.target.tagName !== 'SELECT' && r > 0) {
      event.preventDefault();
      focusCell(r - 1, c);
    }
  };

  const counts = statuses.reduce(
    (acc, s) => ({ ready: acc.ready + (s.text === 'Ready' ? 1 : 0), bad: acc.bad + (s.tone === '#b91c1c' ? 1 : 0) }),
    { ready: 0, bad: 0 }
  );
  const selectedCount = Object.keys(selected).filter(i => selected[i]).length;
  const sample = (templateSample || []).slice(0, 2);
  const linkButton = { background: 'none', border: 0, padding: 0, color: colors.accent, fontSize: 12, fontWeight: 600 };
  const card = { flex: '1 1 220px', border: '1px solid #e8e3f0', borderRadius: 12, padding: 12, background: '#fff' };

  // what the sheet should look like: shown in the paste window, where the sheet is pasted
  const sheetGuide = (
    <div
      style={{ background: '#faf7fd', border: '1px solid #e8e3f0', borderRadius: 12, padding: 14, marginBottom: 12 }}>
      <div style={{ fontWeight: 700, fontSize: 14, color: colors.accentDark, marginBottom: 2 }}>
        What your Excel sheet should look like
      </div>
      <div className="text-muted" style={{ fontSize: 12, marginBottom: 8 }}>
        One row per {what}, and the first row has the column names. The columns can be in any order, and extra columns
        (like S.No) are ignored. <b style={{ color: '#b91c1c' }}>*</b> = must be filled.
      </div>
      <div style={{ overflowX: 'auto' }}>
        <table style={{ borderCollapse: 'collapse', fontSize: 12, background: '#fff' }}>
          <thead>
            <tr>
              {columns.map(col => (
                <th
                  key={col.label}
                  style={{
                    border: '1px solid #d9cfe6',
                    padding: '4px 10px',
                    background: '#efe5f6',
                    color: colors.accentDark,
                    whiteSpace: 'nowrap',
                  }}>
                  {baseName(col)}
                  {col.label.includes('*') && <span style={{ color: '#b91c1c' }}> *</span>}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {sample.map((line, i) => (
              // eslint-disable-next-line react/no-array-index-key
              <tr key={i}>
                {columns.map((col, c) => (
                  <td
                    key={col.label}
                    style={{ border: '1px solid #e4dcee', padding: '4px 10px', whiteSpace: 'nowrap' }}>
                    {line[c]}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {columns.some(col => col.hint) && (
        <ul className="text-muted" style={{ fontSize: 12, margin: '8px 0 0', paddingLeft: 18 }}>
          {columns
            .filter(col => col.hint)
            .map(col => (
              <li key={col.label}>
                <b>{baseName(col)}:</b> {col.hint}
              </li>
            ))}
        </ul>
      )}
    </div>
  );

  return (
    <div
      ref={box}
      onDragOver={e => {
        if (e.dataTransfer?.types?.includes('Files')) {
          e.preventDefault();
          setDragging(true);
        }
      }}
      onDragLeave={() => setDragging(false)}
      onDrop={e => {
        setDragging(false);
        if (e.dataTransfer?.files?.length) {
          e.preventDefault();
          loadFile(e.dataTransfer.files[0]);
        }
      }}
      style={dragging ? { outline: '2px dashed #7c3aed', outlineOffset: 4, borderRadius: 12 } : undefined}>
      <input
        ref={fileInput}
        type="file"
        accept=".xlsx,.xlsm,.xls,.csv,.tsv,.txt"
        style={{ display: 'none' }}
        onChange={e => {
          loadFile(e.target.files[0]);
          e.target.value = ''; // the same file can be chosen again
        }}
      />

      <Modal isOpen={pasteOpen} toggle={closePaste} size="lg" autoFocus={false}>
        <ModalHeader toggle={closePaste}>Paste from Excel</ModalHeader>
        <ModalBody>
          {sheetGuide}
          <div className="text-muted" style={{ fontSize: 13, marginBottom: 8 }}>
            Click in the box below and press <b>Ctrl+V</b> (<b>⌘V</b> on a Mac). Paste the whole sheet with its column
            names, or just the columns you have. Nothing is added to the table until you press &quot;Add to table&quot;.
          </div>
          <textarea
            autoFocus
            value={pasteText}
            onChange={e => setPasteText(e.target.value)}
            placeholder="Click here, then press Ctrl+V to paste what you copied from Excel"
            style={{
              width: '100%',
              minHeight: 110,
              border: `2px dashed ${colors.accent}`,
              borderRadius: 10,
              padding: 10,
              fontFamily: 'monospace',
              fontSize: 12,
              background: '#faf7fd',
              outline: 'none',
              resize: 'vertical',
            }}
          />
          {pasted &&
            (pasted.placed.rows.length ? (
              <div style={{ marginTop: 10 }}>
                <div style={{ fontSize: 13, fontWeight: 700, color: '#15803d' }}>
                  Found {pasted.placed.rows.length} row(s)
                  {pasted.placed.mode === 'header' ? ` with the columns ${pasted.placed.matched.join(', ')}` : ''}.
                </div>
                {!!pasted.placed.ignored.length && (
                  <div className="text-muted" style={{ fontSize: 12 }}>
                    Not used: {pasted.placed.ignored.join(', ')}.
                  </div>
                )}
                {pasted.placed.mode === 'position' && (
                  <div style={{ fontSize: 12, color: '#b45309' }}>
                    No column names found in the first rows, so the cells go into the columns in this order:{' '}
                    {columns.map(baseName).join(', ')}.
                  </div>
                )}
                <div style={{ overflowX: 'auto', marginTop: 6 }}>
                  <table style={{ borderCollapse: 'collapse', fontSize: 12 }}>
                    <thead>
                      <tr>
                        {columns.map(col => (
                          <th
                            key={col.label}
                            style={{ border: '1px solid #d9cfe6', padding: '3px 8px', background: '#efe5f6' }}>
                            {baseName(col)}
                          </th>
                        ))}
                      </tr>
                    </thead>
                    <tbody>
                      {pasted.preview.map((line, i) => (
                        // eslint-disable-next-line react/no-array-index-key
                        <tr key={i}>
                          {line.map((value, c) => (
                            <td
                              key={columns[c].label}
                              style={{ border: '1px solid #e4dcee', padding: '3px 8px', whiteSpace: 'nowrap' }}>
                              {value && value.bad !== undefined ? (
                                <span
                                  style={{ color: '#b45309' }}
                                  title="Not one of the allowed values: it will be reset">
                                  {value.bad} ?
                                </span>
                              ) : (
                                value
                              )}
                            </td>
                          ))}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
                {pasted.placed.rows.length > pasted.preview.length && (
                  <div className="text-muted" style={{ fontSize: 12, marginTop: 4 }}>
                    ... and {pasted.placed.rows.length - pasted.preview.length} more.
                  </div>
                )}
              </div>
            ) : (
              <div style={{ marginTop: 10, fontSize: 13, color: '#b45309' }}>
                Only the column names were found. Copy the rows below them too.
              </div>
            ))}
        </ModalBody>
        <ModalFooter style={{ gap: 12 }}>
          <CustomButton
            size="small"
            name={pasted?.placed.rows.length ? `Add ${pasted.placed.rows.length} row(s) to table` : 'Add to table'}
            disabled={!pasted?.placed.rows.length}
            onClick={addPasted}
          />
          <CustomButton size="small" variant="outlined" name="Discard" onClick={closePaste} />
        </ModalFooter>
      </Modal>

      <div className="text-muted" style={{ fontSize: 12, marginBottom: 8 }}>
        Columns: {columns.map(col => `${baseName(col)}${col.label.includes('*') ? ' *' : ''}`).join(', ')}. One row per{' '}
        {what}. Click <b>Paste from Excel</b> to see an example of the sheet.
      </div>

      {/* three ways to fill the table */}
      <div className="d-flex flex-wrap" style={{ gap: 10, marginBottom: 10 }}>
        <div style={card}>
          <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 6 }}>1. Copy and paste from Excel</div>
          <CustomButton size="small" name="Paste from Excel" onClick={() => setPasteOpen(true)} />
          <ol className="text-muted" style={{ fontSize: 12, margin: '8px 0 0', paddingLeft: 18 }}>
            <li>In Excel, select the sheet (Ctrl+A) and copy it (Ctrl+C).</li>
            <li>
              Click <b>Paste from Excel</b> here.
            </li>
            <li>
              Press <b>Ctrl+V</b> in the window that opens.
            </li>
          </ol>
        </div>
        <div style={card}>
          <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 6 }}>2. Upload the file</div>
          <div className="d-flex flex-wrap align-items-center" style={{ gap: 8 }}>
            <CustomButton
              size="small"
              name="Choose Excel / CSV file"
              onClick={() => fileInput.current && fileInput.current.click()}
            />
            {templateName && (
              <CustomButton
                size="small"
                variant="outlined"
                name="Download blank sheet"
                onClick={() => downloadTemplate(templateName, columns, templateSample)}
              />
            )}
          </div>
          <div className="text-muted" style={{ fontSize: 12, marginTop: 8 }}>
            Accepts .xlsx, .xls or .csv files. You can also drop the file anywhere on this section.
          </div>
        </div>
        <div style={card}>
          <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 6 }}>3. Or type it</div>
          <div className="text-muted" style={{ fontSize: 12 }}>
            Type in the table below. Enter moves down a row, and Ctrl+D copies the box above.
          </div>
        </div>
      </div>

      {note && (
        <div
          style={{
            fontSize: 13,
            color: note.tone,
            marginBottom: 8,
            padding: '6px 10px',
            borderRadius: 8,
            background: '#f7f7fb',
          }}
          role="status">
          {note.text}
        </div>
      )}

      <div className="d-flex flex-wrap align-items-center" style={{ gap: 14, marginBottom: 6 }}>
        <b style={{ fontSize: 13 }}>Check the rows, then create</b>
        <span className="text-muted" style={{ fontSize: 12 }}>
          {counts.ready + counts.bad} with data · {counts.ready} ready · {counts.bad} need fixing
        </span>
        {optionColumn >= 0 && (
          <span className="d-flex align-items-center" style={{ gap: 6, fontSize: 12, marginLeft: 'auto' }}>
            <span className="text-muted">Set {baseName(columns[optionColumn])} of all rows to</span>
            <select
              style={{ ...cell, width: 'auto', padding: '3px 6px' }}
              value={fillValue}
              onChange={e => setFillValue(e.target.value)}>
              <option value="">Choose...</option>
              {columns[optionColumn].options.map(o => (
                <option key={o}>{o}</option>
              ))}
            </select>
            <button type="button" style={linkButton} disabled={!fillValue} onClick={applyToAll}>
              Apply
            </button>
          </span>
        )}
      </div>
      <div style={{ maxHeight: 420, overflow: 'auto', border: '1px solid #e8e3f0', borderRadius: 12 }}>
        <table className="table" style={{ marginBottom: 0 }}>
          <thead>
            <tr>
              <th style={{ width: 36, textAlign: 'center' }}>#</th>
              {columns.map(col => (
                <th key={col.label} style={{ minWidth: col.width || 110 }}>
                  {baseName(col)}
                  {col.label.includes('*') && <span style={{ color: '#b91c1c' }}> *</span>}
                </th>
              ))}
              <th style={{ minWidth: 170 }}>Status</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((row, r) => (
              <tr key={r} style={{ background: row.locked ? '#f0fdf4' : selected[r] ? '#ede1f7' : undefined }}>
                <td
                  style={{ textAlign: 'center', cursor: 'pointer', color: '#6b7280', padding: '0 4px' }}
                  title="Click to select this row"
                  onClick={() => setSelected(prev => ({ ...prev, [r]: !prev[r] }))}>
                  {r + 1}
                </td>
                {columns.map((col, c) => (
                  <td key={col.label} style={{ padding: 3 }}>
                    {col.options ? (
                      <select
                        style={cell}
                        data-r={r}
                        data-c={c}
                        disabled={row.locked}
                        value={row.values[c]}
                        onChange={e => edit(r, c, e.target.value)}
                        onKeyDown={e => keyDown(e, r, c)}>
                        {col.options.map(o => (
                          <option key={o}>{o}</option>
                        ))}
                      </select>
                    ) : (
                      <input
                        style={{
                          ...cell,
                          background: statuses[r].bad.includes(c) ? '#fee2e2' : row.locked ? '#f0fdf4' : '#fff',
                        }}
                        placeholder={col.label.replace(' *', '').replace(' (blank = auto)', '')}
                        data-r={r}
                        data-c={c}
                        readOnly={row.locked}
                        value={row.values[c]}
                        onChange={e => edit(r, c, e.target.value)}
                        onPaste={e => paste(e, r, c)}
                        onKeyDown={e => keyDown(e, r, c)}
                      />
                    )}
                  </td>
                ))}
                <td
                  style={{
                    fontSize: 12,
                    whiteSpace: 'nowrap',
                    color: statuses[r].tone,
                    fontWeight: row.locked ? 700 : 400,
                  }}>
                  {statuses[r].text}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div className="d-flex flex-wrap align-items-center" style={{ gap: 16, marginTop: 8 }}>
        <button
          type="button"
          style={linkButton}
          onClick={() => setRows(prev => withRows(prev, columns, prev.length + 5))}>
          + Add 5 rows
        </button>
        <button type="button" style={linkButton} onClick={undo} disabled={!history.current.length}>
          Undo
        </button>
        <button
          type="button"
          style={linkButton}
          onClick={() => {
            setRows(prev =>
              withRows(
                prev.filter(row => row.locked || !isBlankRow(row.values, defaults)),
                columns,
                minRows
              )
            );
            setSelected({});
          }}>
          Remove empty rows
        </button>
        <button
          type="button"
          style={{ ...linkButton, color: '#b91c1c' }}
          onClick={() => {
            setRows(prev =>
              withRows(
                prev.filter(row => row.locked),
                columns,
                minRows
              )
            );
            setSelected({});
          }}>
          Clear all
        </button>
        {selectedCount > 0 && (
          <button
            type="button"
            style={{ ...linkButton, color: '#b91c1c' }}
            onClick={() => {
              setRows(prev =>
                withRows(
                  prev.filter((row, i) => !selected[i] || row.locked),
                  columns,
                  1
                )
              );
              setSelected({});
            }}>
            Delete {selectedCount} selected row{selectedCount > 1 ? 's' : ''}
          </button>
        )}
        <span className="text-muted" style={{ fontSize: 12 }}>
          Click a row number to select that row.
        </span>
      </div>
    </div>
  );
});

PasteGrid.displayName = 'PasteGrid';

export default PasteGrid;
