import React, { useEffect, useMemo, useState } from 'react';
import { fetchBatchClassesApi, fetchSetupBatchesApi, fetchSubjectTeachersApi } from 'actions/admin/onboarding';
import colors from 'config/colors';
import ChainScroll from '../Common/ChainScroll';

// What step 3 made, shown right in the step: each batch with its own classes, and every class with all its subjects. A school can
// have several batches whose classes differ, so the classes are listed batch by batch (a batch is folded away, the first one is open).
// Read from the school itself (not a summary of the last click), so it is the same after a reload. refreshKey: change it to read
// again (after a create).
const CreatedClassesList = ({ api, refreshKey }) => {
  const [subjects, setSubjects] = useState(null); // null = loading
  const [batches, setBatches] = useState(null); // [{ batchId, name, startYear, endYear, courseIds }]
  const [open, setOpen] = useState({});

  useEffect(() => {
    let cancelled = false;
    fetchSubjectTeachersApi(api)
      .then(list => !cancelled && setSubjects(list || []))
      .catch(() => !cancelled && setSubjects([]));
    fetchSetupBatchesApi(api)
      .then(async list => {
        const found = await Promise.all(
          (Array.isArray(list) ? list : []).map(async batch => {
            const classes = await fetchBatchClassesApi({ ...api, batchId: batch.batchId }).catch(() => []);
            return { ...batch, courseIds: (classes || []).map(c => c.courseId) };
          })
        );
        if (!cancelled) setBatches(found.sort((a, b) => (a.startYear || 0) - (b.startYear || 0)));
      })
      .catch(() => !cancelled && setBatches([]));
    return () => {
      cancelled = true;
    };
  }, [api, refreshKey]);

  // every class (in the order they were made) with its subjects
  const classes = useMemo(() => {
    const byId = new Map();
    (subjects || []).forEach(s => {
      if (!byId.has(s.courseId)) byId.set(s.courseId, { courseId: s.courseId, name: s.courseName, subjects: [] });
      byId.get(s.courseId).subjects.push(s.subjectName);
    });
    return [...byId.values()].sort((a, b) => a.courseId - b.courseId);
  }, [subjects]);

  // the sections: one per batch, and one for classes that are in no batch
  const sections = useMemo(() => {
    if (batches === null) return [];
    const inBatch = new Set();
    const list = batches.map(batch => {
      batch.courseIds.forEach(id => inBatch.add(id));
      return {
        key: `b${batch.batchId}`,
        title: batch.name,
        note: batch.startYear ? `${batch.startYear} - ${batch.endYear}` : '',
        classes: classes.filter(c => batch.courseIds.includes(c.courseId)),
      };
    });
    const loose = classes.filter(c => !inBatch.has(c.courseId));
    if (loose.length) list.push({ key: 'none', title: 'Classes in no batch', note: '', classes: loose });
    return list;
  }, [batches, classes]);

  if (subjects === null || batches === null) return <div className="text-muted">Loading...</div>;
  const subjectTotal = classes.reduce((sum, c) => sum + c.subjects.length, 0);
  const isOpen = (section, i) => (open[section.key] === undefined ? i === 0 : open[section.key]);

  return (
    <div>
      <div className="d-flex flex-wrap" style={{ gap: '4px 24px', fontSize: 13, marginBottom: 10 }}>
        <span>
          <b>{batches.length}</b> batch{batches.length === 1 ? '' : 'es'}
        </span>
        <span>
          <b>{classes.length}</b> classes
        </span>
        <span>
          <b>{subjectTotal}</b> subjects
        </span>
        {batches.length > 1 && (
          <span className="text-muted">Each batch has its own classes; open a batch to see them.</span>
        )}
      </div>
      {sections.map((section, i) => {
        const shown = isOpen(section, i);
        const count = section.classes.reduce((sum, c) => sum + c.subjects.length, 0);
        return (
          <div
            key={section.key}
            style={{ border: '1px solid #e8e3f0', borderRadius: 12, marginBottom: 8, background: '#fff' }}>
            <div
              role="button"
              tabIndex={0}
              className="d-flex flex-wrap align-items-center"
              style={{ gap: '2px 16px', padding: '10px 14px', cursor: 'pointer', fontSize: 13 }}
              onClick={() => setOpen(prev => ({ ...prev, [section.key]: !shown }))}
              onKeyDown={e => e.key === 'Enter' && setOpen(prev => ({ ...prev, [section.key]: !shown }))}>
              <span style={{ color: colors.accent, width: 14 }}>{shown ? '▾' : '▸'}</span>
              <b style={{ fontSize: 14 }}>{section.title}</b>
              {section.note && <span className="text-muted">({section.note})</span>}
              <span className="text-muted">
                {section.classes.length} classes · {count} subjects
              </span>
            </div>
            {shown && (
              <ChainScroll style={{ maxHeight: 380, overflowY: 'auto', borderTop: '1px solid #eceff3' }}>
                <table className="table table-sm mb-0" style={{ fontSize: 13 }}>
                  <thead>
                    <tr>
                      <th style={{ width: 40 }}>#</th>
                      <th style={{ minWidth: 170 }}>Class</th>
                      <th>Subjects</th>
                      <th style={{ width: 80, textAlign: 'right' }}>Count</th>
                    </tr>
                  </thead>
                  <tbody>
                    {section.classes.map((c, n) => (
                      <tr key={c.courseId}>
                        <td className="text-muted">{n + 1}</td>
                        <td style={{ fontWeight: 600 }}>{c.name}</td>
                        <td>
                          {c.subjects.map(name => (
                            <span
                              key={name}
                              style={{
                                display: 'inline-block',
                                margin: '2px 6px 2px 0',
                                padding: '1px 9px',
                                borderRadius: 999,
                                background: '#f3ecfa',
                                color: colors.accentDark,
                                fontSize: 12,
                              }}>
                              {name}
                            </span>
                          ))}
                        </td>
                        <td style={{ textAlign: 'right' }}>{c.subjects.length}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </ChainScroll>
            )}
          </div>
        );
      })}
    </div>
  );
};

export default CreatedClassesList;
